import{_ as a,o as n,c as i,a4 as l}from"./chunks/framework.B-wJupoK.js";const c=JSON.parse('{"title":"18-函数基本使用","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/18-函数定义/18-函数定义.md","filePath":"仓颉入门到实战/18-函数定义/18-函数定义.md","lastUpdated":1734914353000,"__rawMarkdown":"# 18-函数基本使用\\n\\n函数是一些用于代码复用的集合，我们发现某些业务逻辑需要反复使用的时候便可以通过函数来实现。同时，函数也可以让复杂的程序结构按照功能的拆分，使程序更加的健壮合理。\\n\\n## 函数的定义\\n\\n函数的定义有多种不同的写法，先看比较标准的一种。\\n\\n```javascript\\nfunc add(a: Int64, b: Int64): Int64 {\\n    return a + b\\n}\\n```\\n\\n1. `func` 是声明函数的关键字\\n2. `a: Int64`     a是形参，理解成是函数中的独有变量即可，是一个占位符、Int64是它的类型\\n3. b: Int64) : **Int64**    这里Int64 表示返回值的类型\\n4. **return** 表示函数的要返回的值   是  `a+b` \\n\\n## 函数的调用\\n\\n函数调用的固定写法是： **函数名称()**\\n\\n```javascript\\nlet res = add(100, 200) // res = 300\\n```\\n\\n\\n\\n**完整示例**\\n\\n```JavaScript\\n\\nmain() {\\n    let res = add(100, 200)\\n    println(res) // 300 \\n}\\n\\nfunc add(a: Int64, b: Int64): Int64 {\\n    return a + b\\n}\\n```\\n\\n## 函数的参数\\n\\n实际开发中，函数的参数\\n\\n1. 函数的参数可以省略\\n2. 函数的参数可以指定固定的名字\\n3. 函数的参数可以指定默认值\\n\\n\\n\\n### 函数的参数可以省略\\n\\n```javascript\\nmain() {\\n    let res = add()\\n    println(res) // 300 \\n}\\n\\nfunc add(): Int64 {\\n    return 300\\n}\\n```\\n\\n### 函数的参数可以指定固定的名字\\n\\n> 用! 表示指定参数的名字 \\n>\\n> 注意: 命名参数必须放在未命名参数的后面！ \\n\\n```javascript\\nmain() {\\n    // let res = add(100, 200) // 不能直接传递200 ，因为固定了参数的名字是b\\n    let res = add(100, b: 200) // 固定了参数的名字是b\\n    println(res) // 300 \\n}\\n\\nfunc add(a: Int64, b!: Int64): Int64 {\\n    return a + b\\n}\\n```\\n\\n### 函数的参数可以指定默认值\\n\\n> 只能为命名参数设置默认值，不能为非命名参数设置默认值。\\n\\n```javascript\\nmain() {\\n    let res = add(100) // b 被指定了默认值 当不传递b数据的时候 b = 400 ，如果传递了 b = 被传递的内容\\n    println(res) // 500 \\n}\\n\\nfunc add(a: Int64, b!: Int64 = 400): Int64 {\\n    return a + b\\n}\\n\\n```\\n\\n## 函数的返回值\\n\\n如果想要函数运行结束时，返回内容 就可以使用return，当然也可以不使用\\n\\n**有返回值**\\n\\n```javascript\\nmain() {\\n    let res = add()\\n    println(res) // 300 \\n}\\n\\nfunc add() {\\n    return 300 // 有返回值\\n}\\n```\\n\\n**有返回值 省略return**\\n\\n```javascript\\nmain() {\\n    let res = add()\\n    println(res) // 300 \\n}\\n\\nfunc add() {\\n    300 // 有返回值\\n}\\n```\\n\\n\\n\\n**无显式返回值**\\n\\n```javascript\\nmain() {\\n    let res = add()\\n    println(res) // () \\n}\\n\\nfunc add() {\\n     // 无返回值   返回了unit类型 表现形式是 ()\\n}\\n```\\n\\n## 总结\\n\\n在实际开发中可以根据需求来定制我们的函数"}'),p={name:"仓颉入门到实战/18-函数定义/18-函数定义.md"};function e(t,s,h,r,k,d){return n(),i("div",null,[...s[0]||(s[0]=[l("",32)])])}const b=a(p,[["render",e]]);export{c as __pageData,b as default};
